macro_rules! RawMutex {
    () => {
        # [doc = " Raw mutex type backed by the parking lot."] pub struct RawMutex { # [doc = " This atomic integer holds the current state of the mutex instance. Only the two lowest bits"] # [doc = " are used. See `LOCKED_BIT` and `PARKED_BIT` for the bitmask for these bits."] # [doc = ""] # [doc = " # State table:"] # [doc = ""] # [doc = " PARKED_BIT | LOCKED_BIT | Description"] # [doc = "     0      |     0      | The mutex is not locked, nor is anyone waiting for it."] # [doc = " -----------+------------+------------------------------------------------------------------"] # [doc = "     0      |     1      | The mutex is locked by exactly one thread. No other thread is"] # [doc = "            |            | waiting for it."] # [doc = " -----------+------------+------------------------------------------------------------------"] # [doc = "     1      |     0      | The mutex is not locked. One or more thread is parked or about to"] # [doc = "            |            | park. At least one of the parked threads are just about to be"] # [doc = "            |            | unparked, or a thread heading for parking might abort the park."] # [doc = " -----------+------------+------------------------------------------------------------------"] # [doc = "     1      |     1      | The mutex is locked by exactly one thread. One or more thread is"] # [doc = "            |            | parked or about to park, waiting for the lock to become available."] # [doc = "            |            | In this state, PARKED_BIT is only ever cleared when a bucket lock"] # [doc = "            |            | is held (i.e. in a parking_lot_core callback). This ensures that"] # [doc = "            |            | we never end up in a situation where there are parked threads but"] # [doc = "            |            | PARKED_BIT is not set (which would result in those threads"] # [doc = "            |            | potentially never getting woken up)."] state : AtomicU8 , }
    };
}

RawMutex!();